#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const long long MOD = 1000000007;
    long long p, k;
    cin >> p >> k;

    if (k == 0) {
        long long result = 1;
        long long base = p % MOD;
        long long exp = p - 1;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        cout << result << "\n";
    } else if (k == 1) {
        long long result = 1;
        long long base = p % MOD;
        long long exp = p;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        cout << result << "\n";
    } else {
        long long n = k;
        long long order = 1;
        while (n != 1) {
            n = (n * k) % p;
            order++;
        }
        long long loops = (p - 1) / order;
        long long result = 1;
        long long base = p % MOD;
        long long exp = loops;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        cout << result << "\n";
    }

    return 0;
}
